import { test, expect } from '@playwright/test';

test.describe('Notification Deletion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should successfully delete a single notification from the list', async ({ page }) => {
    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify notification item is visible
    const notificationItem = page.getByText('Upcoming Event');
    await expect(notificationItem).toBeVisible();

    // Verify delete button is visible and enabled
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();

    // Click delete button
    await deleteButton.click();

    // Verify confirmation modal appears
    const confirmationModal = page.getByRole('dialog', { name: /confirm/i });
    await expect(confirmationModal).toBeVisible();

    // Verify confirm button is visible and enabled
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button
    await confirmButton.click();

    // Verify notification is removed from list
    await expect(notificationItem).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/notification deleted/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle empty notification list and display error message', async ({ page }) => {
    // Verify notification list is empty
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeEmpty();

    // Verify error message is visible
    const errorMessage = page.getByText(/no notifications/i);
    await expect(errorMessage).toBeVisible();

    // Verify delete button is disabled
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeDisabled();

    // Verify no confirmation modal is visible
    const confirmationModal = page.getByRole('dialog', { name: /confirm/i });
    await expect(confirmationModal).not.toBeVisible();

    // Verify success message is not displayed
    const successMessage = page.getByText(/notification deleted/i);
    await expect(successMessage).not.toBeVisible();
  });
});
